/**
 * Database initialization for reactive demo
 *
 * Creates necessary tables if they don't exist
 */

import { db } from "@/shared/database";

/**
 * Initialize database schema for reactive demo
 * Creates customers table and sample data if needed
 */
export async function initReactiveDemo() {
  try {
    // Create tables if they don't exist
    await db.schema
      .createTable("regions")
      .ifNotExists()
      .addColumn("region_id", "integer", (col) => col.primaryKey())
      .addColumn("region_name", "text", (col) => col.notNull())
      .execute();

    await db.schema
      .createTable("countries")
      .ifNotExists()
      .addColumn("country_id", "integer", (col) => col.primaryKey())
      .addColumn("country_name", "text", (col) => col.notNull())
      .addColumn("region_id", "integer", (col) => col.notNull())
      .execute();

    await db.schema
      .createTable("customers")
      .ifNotExists()
      .addColumn("customer_id", "integer", (col) => col.primaryKey())
      .addColumn("customer_name", "text", (col) => col.notNull())
      .addColumn("country_id", "integer", (col) => col.notNull())
      .execute();

    // Add sample data if customers table is empty
    const existingCustomers = await db
      .selectFrom("customers")
      .selectAll()
      .execute();

    if (existingCustomers.length === 0) {
      // Insert sample regions
      await db
        .insertInto("regions")
        .values([
          { region_id: 1, region_name: "North America" },
          { region_id: 2, region_name: "Europe" },
        ])
        .execute();

      // Insert sample countries
      await db
        .insertInto("countries")
        .values([
          { country_id: 1, country_name: "USA", region_id: 1 },
          { country_id: 2, country_name: "Canada", region_id: 1 },
          { country_id: 3, country_name: "UK", region_id: 2 },
          { country_id: 4, country_name: "France", region_id: 2 },
        ])
        .execute();

      // Insert sample customers
      await db
        .insertInto("customers")
        .values([
          { customer_id: 1, customer_name: "John Doe", country_id: 1 },
          { customer_id: 2, customer_name: "Jane Smith", country_id: 2 },
          { customer_id: 3, customer_name: "Bob Johnson", country_id: 1 },
        ])
        .execute();

      console.log("✅ Reactive demo database initialized with sample data");
    } else {
      console.log("✅ Reactive demo database already initialized");
    }

    return true;
  } catch (error) {
    console.error("❌ Failed to initialize reactive demo database:", error);
    return false;
  }
}

/**
 * Check if database is initialized
 */
export async function isDatabaseInitialized(): Promise<boolean> {
  try {
    await db.selectFrom("customers").selectAll().limit(1).execute();
    return true;
  } catch {
    return false;
  }
}
