<template>
  <F7Page name="reactive">
    <F7Navbar title="Reactive DB Demo" back-link="Back" />

    <!-- Initialization Loading -->
    <F7Block v-if="isInitializing" strong inset class="text-align-center">
      <F7Preloader />
      <p class="margin-top">Initializing database...</p>
    </F7Block>

    <!-- Initialization Error -->
    <F7Block v-else-if="initError" strong inset class="bg-red-50">
      <p class="text-color-red">
        <F7Icon f7="exclamationmark_triangle" /> {{ initError }}
      </p>
      <F7Button fill @click="refreshPage"> Refresh Page </F7Button>
    </F7Block>

    <!-- Main Content (only show after initialization) -->
    <template v-else>
      <F7BlockTitle large>Live Reactive Database</F7BlockTitle>
      <F7Block strong inset class="text-align-center">
        <p>
          This demo shows <strong>real-time reactivity</strong> - changes to the
          database automatically update the UI!
        </p>
        <p class="text-color-gray">
          Try adding, editing, or deleting customers below.
        </p>
      </F7Block>

      <!-- Stats Card -->
      <F7Block strong inset>
        <div class="flex justify-between items-center">
          <div>
            <div class="text-color-gray">Total Customers</div>
            <div class="text-2xl font-bold">{{ totalCustomers }}</div>
          </div>
          <div>
            <F7Button
              fill
              icon-f7="plus"
              @click="openAddDialog"
              :disabled="isAdding"
            >
              Add Customer
            </F7Button>
          </div>
        </div>
      </F7Block>

      <!-- Loading State -->
      <F7BlockTitle v-if="loading && !customers" medium
        >Loading customers...</F7BlockTitle
      >

      <!-- Error State -->
      <F7Block v-if="error" strong inset class="bg-red-50">
        <p class="text-color-red">
          <F7Icon f7="exclamationmark_triangle" /> Error loading customers:
          {{ error.message }}
        </p>
      </F7Block>

      <!-- Customer List -->
      <F7List v-if="customers && customers.length > 0" strong inset dividers>
        <F7ListItem
          v-for="customer in customers"
          :key="customer.customer_id"
          :title="customer.customer_name"
          :after="`Country ID: ${customer.country_id}`"
          swipeout
        >
          <F7SwipeoutActions right>
            <F7SwipeoutButton
              color="blue"
              @click="openEditDialog(customer)"
              :disabled="isUpdating"
            >
              <F7Icon f7="pencil" />
            </F7SwipeoutButton>
            <F7SwipeoutButton
              color="red"
              @click="handleDelete(customer.customer_id)"
              :disabled="isDeleting"
            >
              <F7Icon f7="trash" />
            </F7SwipeoutButton>
          </F7SwipeoutActions>
        </F7ListItem>
      </F7List>

      <!-- Empty State -->
      <F7Block v-else-if="customers && customers.length === 0" strong inset>
        <div class="text-align-center text-color-gray">
          <F7Icon f7="tray" size="48px" class="margin-bottom" />
          <p>No customers yet. Add one to get started!</p>
        </div>
      </F7Block>

      <!-- Info Footer -->
      <F7BlockTitle medium>✨ Reactive Features</F7BlockTitle>
      <F7List strong inset>
        <F7ListItem title="Optimistic Updates">
          <template #after>
            <F7Badge color="green">✓</F7Badge>
          </template>
        </F7ListItem>
        <F7ListItem title="Auto Refetch on Change">
          <template #after>
            <F7Badge color="green">✓</F7Badge>
          </template>
        </F7ListItem>
        <F7ListItem title="Error Rollback">
          <template #after>
            <F7Badge color="green">✓</F7Badge>
          </template>
        </F7ListItem>
      </F7List>
    </template>

    <!-- Add/Edit Dialog -->
    <F7Popup
      :opened="dialogOpened"
      @popup:closed="dialogOpened = false"
      swipe-to-close
    >
      <F7Page>
        <F7Navbar :title="editingCustomer ? 'Edit Customer' : 'Add Customer'">
          <F7NavRight>
            <F7Link popup-close>Close</F7Link>
          </F7NavRight>
        </F7Navbar>

        <F7Block strong inset>
          <F7List strong-ios inset-ios>
            <F7ListInput
              v-model:value="form.customer_name"
              label="Customer Name"
              type="text"
              placeholder="Enter name"
              clear-button
            />
            <F7ListInput
              v-model:value="form.country_id"
              label="Country ID"
              type="number"
              placeholder="Enter country ID"
              clear-button
            />
          </F7List>

          <F7Button
            fill
            large
            @click="handleSubmit"
            :disabled="!isFormValid || isAdding || isUpdating"
          >
            {{ editingCustomer ? "Update" : "Add" }} Customer
          </F7Button>
        </F7Block>
      </F7Page>
    </F7Popup>
  </F7Page>
</template>

<script setup lang="ts">
import { ref, computed, onMounted } from "vue";
import { f7 } from "framework7-vue";
import { useCustomers } from "@/modules/home/composables/useCustomers";
import {
  initReactiveDemo,
  isDatabaseInitialized,
} from "@/modules/reactive/composables/useReactiveDemo";
import type { CustomerTable } from "@/modules/home/database/schema";

// Database initialization state
const isInitializing = ref(true);
const initError = ref<string | null>(null);

// Initialize database on mount
onMounted(async () => {
  try {
    const isInitialized = await isDatabaseInitialized();

    if (!isInitialized) {
      console.log("Initializing reactive demo database...");
      const success = await initReactiveDemo();

      if (!success) {
        initError.value =
          "Failed to initialize database. Please refresh the page.";
      }
    }
  } catch (error) {
    console.error("Database initialization error:", error);
    initError.value =
      "Database initialization failed. Please refresh the page.";
  } finally {
    isInitializing.value = false;
  }
});

// Use reactive customers composable
const {
  customers,
  totalCustomers,
  loading,
  error,
  isAdding,
  isUpdating,
  isDeleting,
  addCustomer,
  updateCustomer,
  deleteCustomer,
} = useCustomers();

// Dialog state
const dialogOpened = ref(false);
const editingCustomer = ref<CustomerTable | null>(null);

// Form data
const form = ref({
  customer_name: "",
  country_id: 1,
});

// Computed
const isFormValid = computed(() => {
  return (
    form.value.customer_name.trim().length > 0 && form.value.country_id > 0
  );
});

// Methods
function refreshPage() {
  window.location.reload();
}

function openAddDialog() {
  editingCustomer.value = null;
  form.value = { customer_name: "", country_id: 1 };
  dialogOpened.value = true;
}

function openEditDialog(customer: CustomerTable) {
  editingCustomer.value = customer;
  form.value = {
    customer_name: customer.customer_name,
    country_id: customer.country_id,
  };
  dialogOpened.value = true;
}

async function handleSubmit() {
  if (!isFormValid.value) return;

  try {
    if (editingCustomer.value) {
      // Update existing customer (optimistic update!)
      await updateCustomer({
        id: editingCustomer.value.customer_id,
        name: form.value.customer_name,
      });

      f7.toast
        .create({
          text: "Customer updated! 🎉",
          position: "center",
          closeTimeout: 2000,
        })
        .open();
    } else {
      // Add new customer (optimistic update!)
      await addCustomer({
        customer_name: form.value.customer_name,
        country_id: form.value.country_id,
      });

      f7.toast
        .create({
          text: "Customer added! ✨",
          position: "center",
          closeTimeout: 2000,
        })
        .open();
    }

    dialogOpened.value = false;
  } catch (err) {
    console.error("Form submission error:", err);
  }
}

async function handleDelete(customerId: number) {
  const confirmed = await new Promise((resolve) => {
    f7.dialog.confirm(
      "Are you sure you want to delete this customer?",
      "Delete Customer",
      () => resolve(true),
      () => resolve(false),
    );
  });

  if (!confirmed) return;

  try {
    // Delete customer (optimistic update with rollback!)
    await deleteCustomer(customerId);

    f7.toast
      .create({
        text: "Customer deleted! 🗑️",
        position: "center",
        closeTimeout: 2000,
      })
      .open();
  } catch (err) {
    console.error("Delete error:", err);
  }
}
</script>

<style scoped>
.flex {
  display: flex;
}

.justify-between {
  justify-content: space-between;
}

.items-center {
  align-items: center;
}

.text-2xl {
  font-size: 1.5rem;
}

.font-bold {
  font-weight: bold;
}

.margin-bottom {
  margin-bottom: 1rem;
}

.bg-red-50 {
  background-color: rgba(255, 0, 0, 0.05);
}

.text-align-center {
  text-align: center;
}
</style>
